import type { LucideIcon } from 'lucide-react'
import type { ButtonHTMLAttributes } from 'react'

type Props = ButtonHTMLAttributes<HTMLButtonElement> & {
  icon?: LucideIcon
  label: string
}

export function ActionPillButton({ icon: Icon, label, className, ...props }: Props) {
  return (
    <button
      {...props}
      className={`inline-flex items-center gap-2 px-4 py-2 rounded-pill text-sm font-medium text-white transition-opacity hover:opacity-90 disabled:opacity-50 ${className ?? ''}`}
      style={{ background: 'linear-gradient(135deg, hsl(var(--gradient-from)), hsl(var(--gradient-to)))' }}
    >
      {Icon && <Icon size={16} />}
      {label}
    </button>
  )
}
